            lineas: ["<html>", "<head><title>Mi equipo informático</title></head>", "<body bgcolor=\"LIGHTCYAN\" color=\"DARKBLUE\">", "<hr width=\"90%\" height=\"6\" align=\"center\" noshade>", "<h1 align=\"center\"><font face=\"Courier New\">MI EQUIPO INFORMÁTICO</font></h1>", "<ol type=\"a\">", "  <li>Sistema operativo</li>", "  <li>Navegador web</li>", "</ol>", "<dl>", "  <dt>CPU</dt>", "  <li>Unidad Central de Procesamiento.</li>", "</dl>", "</body>", "</html>"],
            errores: { 3: { fix: '<body bgcolor="LIGHTCYAN" text="DARKBLUE">', why: "En el body el color del texto es <code>text</code>, no <code>color</code>." }, 4: { fix: '<hr width="90%" size="6" align="center" noshade>', why: "El grosor de hr se pone con <code>size</code>." }, 6: { fix: '<ol type="A">', why: "Letras <b>mayúsculas</b> → <code>type=\"A\"</code>. <code>\"a\"</code> son minúsculas." }, 12: { fix: "  <dd>Unidad Central de Procesamiento.</dd>", why: "En una lista de definición la definición va en <code>&lt;dd&gt;</code>; <code>&lt;li&gt;</code> es para ul/ol." } },
            trampas: { 5: "Está bien: la alineación va en el h1 y la fuente en el font de dentro." },
